// FindSet opens a result set matching current filters (BC/NAV style)
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *CustomerBase) FindSet() bool {
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CustomerTableName)
	where, args := t.buildWhereClause()
	orderBy := t.getOrderByClause()

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, name, address, post_code, city, phonenumber, payment_terms_code, status, credit_limit, last_order_date, created_at, profile_photo FROM "%s" WHERE %s ORDER BY %s`, tableName, where, orderBy)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Customer: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record in the result set (BC/NAV style)
// Must be called after FindSet() or FindSetBuffered()
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (only with FindSetBuffered)
//   - Next(-3): Skip backward 3 records (only with FindSetBuffered)
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *CustomerBase) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var noNull sql.NullString
		var nameNull sql.NullString
		var addressNull sql.NullString
		var post_codeNull sql.NullString
		var cityNull sql.NullString
		var phonenumberNull sql.NullString
		var payment_terms_codeNull sql.NullString
		var statusInt int
		var credit_limitNull sql.NullString
		var last_order_dateNull sql.NullString
		var created_atNull sql.NullString

		err := t.currentRows.Scan(
			&noNull,
			&nameNull,
			&addressNull,
			&post_codeNull,
			&cityNull,
			&phonenumberNull,
			&payment_terms_codeNull,
			&statusInt,
			&credit_limitNull,
			&last_order_dateNull,
			&created_atNull,
			&t.Profile_photo,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Customer record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.No = types.NewCode(noNull.String)
		t.Name = types.NewText(nameNull.String)
		t.Address = types.NewText(addressNull.String)
		t.Post_code = types.NewCode(post_codeNull.String)
		t.City = types.NewText(cityNull.String)
		t.Phonenumber = types.NewText(phonenumberNull.String)
		t.Payment_terms_code = types.NewCode(payment_terms_codeNull.String)
		t.Status = CustomerStatus(statusInt)
		t.Credit_limit, _ = types.NewDecimalFromString(credit_limitNull.String)
		t.Last_order_date, _ = types.NewDateFromString(last_order_dateNull.String)
		t.Created_at, _ = types.NewDateTimeFromString(created_atNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No active recordset
	return false
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation (BC/NAV style)
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *CustomerBase) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, CustomerTableName)
	where, args := t.buildWhereClause()
	orderBy := t.getOrderByClause()

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, name, address, post_code, city, phonenumber, payment_terms_code, status, credit_limit, last_order_date, created_at, profile_photo FROM "%s" WHERE %s ORDER BY %s`, tableName, where, orderBy)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Customer: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &CustomerBase{}
		record.db = t.db
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var noNull sql.NullString
		var nameNull sql.NullString
		var addressNull sql.NullString
		var post_codeNull sql.NullString
		var cityNull sql.NullString
		var phonenumberNull sql.NullString
		var payment_terms_codeNull sql.NullString
		var statusInt int
		var credit_limitNull sql.NullString
		var last_order_dateNull sql.NullString
		var created_atNull sql.NullString

		err := rows.Scan(
			&noNull,
			&nameNull,
			&addressNull,
			&post_codeNull,
			&cityNull,
			&phonenumberNull,
			&payment_terms_codeNull,
			&statusInt,
			&credit_limitNull,
			&last_order_dateNull,
			&created_atNull,
			&record.Profile_photo,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Customer record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.No = types.NewCode(noNull.String)
		record.Name = types.NewText(nameNull.String)
		record.Address = types.NewText(addressNull.String)
		record.Post_code = types.NewCode(post_codeNull.String)
		record.City = types.NewText(cityNull.String)
		record.Phonenumber = types.NewText(phonenumberNull.String)
		record.Payment_terms_code = types.NewCode(payment_terms_codeNull.String)
		record.Status = CustomerStatus(statusInt)
		record.Credit_limit, _ = types.NewDecimalFromString(credit_limitNull.String)
		record.Last_order_date, _ = types.NewDateFromString(last_order_dateNull.String)
		record.Created_at, _ = types.NewDateTimeFromString(created_atNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Customer records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *CustomerBase) copyFromBuffered(record *CustomerBase) {
	t.No = record.No
	t.Name = record.Name
	t.Address = record.Address
	t.Post_code = record.Post_code
	t.City = record.City
	t.Phonenumber = record.Phonenumber
	t.Payment_terms_code = record.Payment_terms_code
	t.Status = record.Status
	t.Credit_limit = record.Credit_limit
	t.Last_order_date = record.Last_order_date
	t.Created_at = record.Created_at
	t.Profile_photo = record.Profile_photo
	t.Balance_lcy = record.Balance_lcy
	t.Sales_lcy = record.Sales_lcy
	t.No_of_ledger_entries = record.No_of_ledger_entries
	t.StoreOldValues()
}

